-- feat-onboarding-trial : essai gratuit de l'onboarding rider en 3 séances
-- (test FTP classique, seuil en positions imposées, sprints en positions
-- imposées), débloquées dans l'ordre.
--
-- * users.trial_sessions_done : séances d'essai faites (0–3), écrite par
--   l'app à l'enregistrement de la séance attendue ;
-- * 2 séances (intensités des séances perso du fondateur, FTP 299 W) :
--   seuil 3 × 7' à 97 % FTP / 4' à 60 % (prolongateurs, drops aéro,
--   cocottes) ; sprints 6 × 20'' à 150 % FTP / 4' à 75 %, positions
--   alternées. Échauffement 5' 45→100 % + 5' à 74 %, retour au calme 5'
--   70→45 %.

ALTER TABLE public.users
  ADD COLUMN trial_sessions_done smallint NOT NULL DEFAULT 0
    CHECK (trial_sessions_done BETWEEN 0 AND 3);

GRANT UPDATE (trial_sessions_done) ON public.users TO authenticated;

INSERT INTO public.training_sessions (name, info, session_json, total_duration, is_test, live_comments, translations_json, aero_duration_sec)
SELECT 'trial_threshold_session_name', 'trial_threshold_session_info', '{"nom": "Essai 2 · Seuil en positions", "infos": "", "duration": 44, "UnitDisplay": "% FTP", "blocks": [{"type": "Grad+", "unit": "% FTP", "power_start": 45.0, "power_end": 100.0, "duration_work": 300}, {"type": "CONST", "unit": "% FTP", "power_start": 74.0, "duration_work": 300}, {"type": "CONST", "unit": "% FTP", "power_start": 97.0, "duration_work": 420, "position": "prolongateurs"}, {"type": "CONST", "unit": "% FTP", "power_start": 60.0, "duration_work": 240}, {"type": "CONST", "unit": "% FTP", "power_start": 97.0, "duration_work": 420, "position": "drops_aggro"}, {"type": "CONST", "unit": "% FTP", "power_start": 60.0, "duration_work": 240}, {"type": "CONST", "unit": "% FTP", "power_start": 97.0, "duration_work": 420, "position": "cocottes"}, {"type": "Grad-", "unit": "% FTP", "power_start": 70.0, "power_end": 45.0, "duration_work": 300}]}'::jsonb, 44, false, '[{"at": 540, "key": "trial_next_block_prolongateurs", "duration": 12}, {"at": 600, "key": "trial_hold_position", "duration": 12}, {"at": 1200, "key": "trial_next_block_drops_aggro", "duration": 12}, {"at": 1260, "key": "trial_hold_position", "duration": 12}, {"at": 1860, "key": "trial_next_block_cocottes", "duration": 12}, {"at": 1920, "key": "trial_hold_position", "duration": 12}]'::jsonb, '{"name": {"fr": "Essai 2 · Seuil en positions", "en": "Trial 2 · Threshold in positions", "es": "Prueba 2 · Umbral en posiciones", "it": "Prova 2 · Soglia in posizioni", "de": "Test 2 · Schwelle in Positionen", "nl": "Proef 2 · Drempel in posities", "pt": "Teste 2 · Limiar em posições", "ja": "トライアル2 · ポジション別閾値", "tr": "Deneme 2 · Pozisyonlarda eşik"}}'::jsonb, 840
WHERE NOT EXISTS (SELECT 1 FROM public.training_sessions WHERE name = 'trial_threshold_session_name');

